package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.chronicle.*; import com.wizzadrds.theworldremembers.voice.VoicePacket; import net.fabricmc.api.ClientModInitializer; import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents; import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper; import com.mojang.blaze3d.platform.InputConstants; import net.minecraft.client.KeyMapping; import org.lwjgl.glfw.GLFW; import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking; import net.minecraft.client.Minecraft; public final class TheWorldRemembersClient implements ClientModInitializer{private static final KeyMapping CHRONICLE_KEY=KeyBindingHelper.registerKeyBinding(new KeyMapping("key.the_world_remembers.chronicles",InputConstants.Type.KEYSYM,GLFW.GLFW_KEY_J,"key.categories.misc"));private static volatile VoicePacket lastVoice; public static VoicePacket lastVoice(){return lastVoice;} public void onInitializeClient(){ClientPlayNetworking.registerGlobalReceiver(VoicePacket.TYPE,(payload,context)->lastVoice=payload);ClientPlayNetworking.registerGlobalReceiver(ChronicleResponsePacket.TYPE,(payload,context)->Minecraft.getInstance().execute(()->Minecraft.getInstance().setScreen(new ChronicleScreen(payload.lines()))));ClientTickEvents.END_CLIENT_TICK.register(client->{while(CHRONICLE_KEY.consumeClick())openChronicles();});} public static void openChronicles(){ChronicleNetworking.request();}}